The slow SMA period was unspecified, so this implementation uses 20 completed five-minute bars.

```python
from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyBullishCallAlgorithm(QCAlgorithm):

    FAST_PERIOD = 5
    SLOW_PERIOD = 20
    OPTION_DTE = 7

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 730)
        )

        self.fast_values = deque(maxlen=self.FAST_PERIOD)
        self.slow_values = deque(maxlen=self.SLOW_PERIOD)

        self.previous_fast = None
        self.previous_slow = None

        self.bucket_date = None
        self.bucket_start = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.entry_order_id = None
        self.entry_price = None

        self.held_symbol = None
        self.exit_ticket = None
        self.exit_order_id = None

        self.expiration_block_date = None
        self.time_stop_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        # Immediately remove any unexpected SPY equity position.
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            self.Debug(
                f"{self.Time}: Unexpected SPY equity position detected "
                f"({spy_quantity}); liquidating immediately."
            )
            self.MarketOrder(self.spy, -spy_quantity)
            self.expiration_block_date = today

        # Expiration protection takes precedence over all other processing.
        if self.held_symbol is not None:
            expiration_date = self._expiration_date(self.held_symbol)

            if today >= expiration_date:
                self.expiration_block_date = today
                self._submit_exit("expiration processing")
            else:
                self._evaluate_option_exit(slice, today, expiration_date)

        # Do not enter on the expiration-processing date.
        if self.expiration_block_date == today:
            return

        bar = slice.Bars.get(self.spy)
        if bar is None:
            return

        self._update_five_minute_bar(bar, slice)

    def _update_five_minute_bar(self, minute_bar, slice):
        start_time = minute_bar.EndTime - timedelta(minutes=1)
        local_date = start_time.date()

        if start_time.hour < 9 or (
            start_time.hour == 9 and start_time.minute < 30
        ):
            return

        if start_time.hour > 16 or (
            start_time.hour == 16 and start_time.minute > 0
        ):
            return

        session_start = start_time.replace(
            hour=9, minute=30, second=0, microsecond=0
        )

        elapsed_minutes = int((start_time - session_start).total_seconds() // 60)
        bucket_offset = elapsed_minutes // 5
        bucket_start = session_start + timedelta(minutes=bucket_offset * 5)
        bucket_end = bucket_start + timedelta(minutes=5)

        if self.bucket_date != local_date:
            self.bucket_date = local_date
            self.bucket_start = None
            self.bucket_bars = {}

        if self.bucket_start is not None and bucket_start != self.bucket_start:
            self._complete_bucket(self.bucket_start, slice)

        if self.bucket_start != bucket_start:
            self.bucket_start = bucket_start
            self.bucket_bars = {}

        minute_key = start_time
        self.bucket_bars[minute_key] = minute_bar

        # A five-minute bar is completed exactly at its aligned boundary.
        if minute_bar.EndTime >= bucket_end:
            self._complete_bucket(bucket_start, slice)
            self.bucket_start = None
            self.bucket_bars = {}

    def _complete_bucket(self, bucket_start, slice):
        if len(self.bucket_bars) != 5:
            # Missing minute data means the consolidated interval is discarded.
            return

        expected = [
            bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if any(timestamp not in self.bucket_bars for timestamp in expected):
            return

        bars = [self.bucket_bars[timestamp] for timestamp in expected]
        close = float(bars[-1].Close)
        bucket_end = bucket_start + timedelta(minutes=5)

        self._process_five_minute_close(close, bucket_end, slice)

    def _process_five_minute_close(self, close, bar_end, slice):
        if bar_end.hour < 9 or (
            bar_end.hour == 9 and bar_end.minute < 45
        ):
            eligible_time = False
        else:
            eligible_time = (
                bar_end.hour < 14
                or (bar_end.hour == 14 and bar_end.minute <= 30)
            )

        old_fast = self.previous_fast
        old_slow = self.previous_slow

        self.fast_values.append(close)
        self.slow_values.append(close)

        current_fast = None
        current_slow = None

        if len(self.fast_values) == self.FAST_PERIOD:
            current_fast = sum(self.fast_values) / self.FAST_PERIOD

        if len(self.slow_values) == self.SLOW_PERIOD:
            current_slow = sum(self.slow_values) / self.SLOW_PERIOD

        bullish_cross = (
            old_fast is not None
            and old_slow is not None
            and current_fast is not None
            and current_slow is not None
            and old_fast <= old_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if not eligible_time or not bullish_cross:
            return

        if self.held_symbol is not None or self._entry_order_open():
            return

        self._enter_call(slice, close)

    def _enter_call(self, slice, spy_price):
        chains = slice.OptionChains
        chain = chains.get(self.spy_option.Symbol)

        if chain is None:
            self.Debug(f"{self.Time}: Skipped call selection; no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiration = current_date + timedelta(days=self.OPTION_DTE)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiration
        })

        if not expirations:
            self.Debug(
                f"{self.Time}: Skipped call selection; "
                f"no expiration at least {self.OPTION_DTE} days away."
            )
            return

        selected_expiration = expirations[0]
        minimum_strike = 1.01 * float(spy_price)

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiration
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: Skipped call selection; "
                f"no qualifying call at expiration {selected_expiration}."
            )
            return

        candidates.sort(
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = self.entry_ticket.OrderId

        self.Debug(
            f"{self.Time}: Submitted market entry for "
            f"{selected.Symbol}."
        )

    def _evaluate_option_exit(self, slice, today, expiration_date):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self._exit_order_open():
            return

        quote = slice.QuoteBars.get(self.held_symbol)

        if quote is not None:
            bid = float(quote.Bid.Close)
            ask = float(quote.Ask.Close)

            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0

                if midpoint >= 1.50 * self.entry_price:
                    self._submit_exit("50% profit target")
                    return

        if self._is_pre_expiration_trading_day(today, expiration_date):
            if self.Time.hour > 15 or (
                self.Time.hour == 15 and self.Time.minute >= 45
            ):
                self._submit_exit("pre-expiration time stop")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self._exit_order_open():
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.exit_order_id = self.exit_ticket.OrderId

        self.Debug(
            f"{self.Time}: Submitted market exit for "
            f"{self.held_symbol}; reason: {reason}."
        )

    def OnOrderEvent(self, order_event):
        status = order_event.Status

        if (
            self.entry_order_id is not None
            and order_event.OrderId == self.entry_order_id
        ):
            if status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)

                self.Debug(
                    f"{self.Time}: Call entry filled: "
                    f"{self.held_symbol} at {self.entry_price:.4f}."
                )

            elif status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None
            ):
                self.entry_ticket = None
                self.entry_order_id = None

        if (
            self.exit_order_id is not None
            and order_event.OrderId == self.exit_order_id
        ):
            if status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: Call exit filled: "
                    f"{order_event.Symbol} at "
                    f"{float(order_event.FillPrice):.4f}."
                )

                self.exit_ticket = None
                self.exit_order_id = None
                self.held_symbol = None
                self.entry_price = None

            elif status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None
            ):
                self.exit_ticket = None
                self.exit_order_id = None

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _exit_order_open(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _expiration_date(self, symbol):
        security = self.Securities[symbol]
        return security.Symbol.ID.Date.date()

    def _is_pre_expiration_trading_day(self, current_date, expiration_date):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = expiration_date - timedelta(days=1)

        while candidate >= current_date - timedelta(days=10):
            candidate_datetime = datetime(
                candidate.year, candidate.month, candidate.day
            )

            if exchange_hours.IsDateOpen(candidate_datetime):
                return candidate == current_date

            candidate -= timedelta(days=1)

        return False
