from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):
    FAST_PERIOD = 5
    SLOW_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.spy_symbol = self.spy.Symbol
        self.option_symbol = self.option.Symbol

        self.closes = deque(maxlen=self.SLOW_PERIOD)
        self.previous_fast = None
        self.previous_slow = None

        self.minute_bucket_key = None
        self.minute_bucket = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.position_symbol = None
        self.entry_price = None
        self.no_entry_date = None

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy_symbol),
            self.TimeRules.At(15, 45),
            self.CheckTimeStop
        )

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy_symbol),
            self.TimeRules.At(9, 31),
            self.CheckExpirationProcessing
        )

    def OnData(self, slice: Slice):
        if self.spy_symbol not in slice.Bars:
            return

        bar = slice.Bars[self.spy_symbol]
        local_time = bar.EndTime
        current_time = local_time.time()

        # Only regular-session minute bars are used.
        if current_time <= time(9, 30) or current_time > time(16, 0):
            return

        minute = local_time.minute
        bucket_end_minute = ((minute + 4) // 5) * 5
        bucket_end_date = local_time.date()

        if bucket_end_minute > 60:
            return

        bucket_key = (bucket_end_date, bucket_end_minute)

        if self.minute_bucket_key != bucket_key:
            self.minute_bucket_key = bucket_key
            self.minute_bucket = {}

        # Duplicate minute data must not be counted twice.
        self.minute_bucket[minute] = bar

        # A five-minute bar closes on clock minutes divisible by five.
        if minute % 5 != 0:
            return

        expected_minutes = [bucket_end_minute - i for i in range(1, 6)]

        # Missing minute data means the consolidated bar is missing.
        if any(m not in self.minute_bucket for m in expected_minutes):
            self.minute_bucket = {}
            return

        completed_bars = [
            self.minute_bucket[m]
            for m in sorted(expected_minutes)
        ]

        close_price = float(completed_bars[-1].Close)
        completed_end = local_time

        self.minute_bucket = {}
        self.OnFiveMinuteBar(completed_end, close_price, slice)

    def OnFiveMinuteBar(self, bar_end, close_price, slice):
        if len(self.closes) >= self.FAST_PERIOD:
            previous_fast = sum(
                list(self.closes)[-self.FAST_PERIOD:]
