from datetime import timedelta

from QuantConnect import Resolution, Market, TimeZones
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Data.Market import QuoteBar
from QuantConnect.Orders import OrderStatus, OrderType
from QuantConnect.Securities import DataNormalizationMode
from QuantConnect.Securities.Option import OptionRight
from QuantConnect.Indicators import RollingWindow


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    FAST_PERIOD = 5
    SLOW_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        spy_security = self.AddEquity(
            "SPY",
            Resolution.Minute,
            Market.USA,
            True,
            0,
            False
        )
        spy_security.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = spy_security

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(0, 730)
        )

        self.fast_window = RollingWindow[float](self.FAST_PERIOD)
        self.slow_window = RollingWindow[float](self.SLOW_PERIOD)
        self.previous_fast = None
        self.previous_slow = None

        self.active_bucket_end = None
        self.minute_bars = {}

        self.option_symbol = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_fill_price = None
        self.no_entry_date = None

    def OnData(self, slice):
        self._HandleUnexpectedEquityPosition()
        self._HandleExpirationProcessing()
        self._EvaluateOpenPositionExit(slice)
        self._ResetFlatState()

        if not slice.Bars.ContainsKey(self.spy.Symbol):
            return

        minute_bar = slice.Bars[self.spy.Symbol]
        completed_bar = self._UpdateFiveMinuteBar(minute_bar)

        if completed_bar is None:
            return

        end_time, close = completed_bar
        self._UpdateMovingAverages(close)

        if not self.fast_window.IsReady or not self.slow_window.IsReady:
            return

        if self.previous_fast is not None and self.previous_slow is not None:
            bullish_crossover = (
                self.previous_fast <= self.previous_slow
                and self.fast_window[0] > self.slow_window[0]
            )

            eligible_time = (
                (end_time.hour > 9 or
                 (end_time.hour == 9 and end_time.minute >= 45))
                and
                (end_time.hour < 14 or
                 (end_time.hour == 14 and end_time.minute <= 30))
            )

            if bullish_crossover and eligible_time:
                self._TryEnter(slice)

        self.previous_fast = self.fast_window[0]
        self.previous_slow = self.slow_window[0]

    def _UpdateFiveMinuteBar(self, minute_bar):
        end_time = minute_bar.EndTime.replace(second=0, microsecond=0)
        minute_number = end_time.hour * 60 + end_time.minute

        bucket_minute = ((minute_number + 4) // 5) * 5
        bucket_hour = bucket_minute // 60
        bucket_minute %= 60

        bucket_end = end_time.replace(
            hour=bucket_hour,
            minute=bucket_minute
        )

        if (
            self.active_bucket_end is not None
            and bucket_end != self.active_bucket_end
        ):
            self.minute_bars = {}

        self.active_bucket_end = bucket_end
        self.minute_bars[end_time] = minute_bar

        expected_times = [
            bucket_end - timedelta(minutes=i)
            for i in range(5)
        ]

        if not all(t in self.minute_bars for t in expected_times):
            return None

        close = self.minute_bars[bucket_end].Close
        self.minute_bars = {}
        self.active_bucket_end = None

        return bucket_end, close

    def _UpdateMovingAverages(self, close):
        self.fast_window.Add(float(close))
        self.slow_window.Add(float(close))

    def _TryEnter(self, slice):
        current_date = self.Time.date()

        if self.no_entry_date == current_date:
            return

        if self.entry_ticket is not None and self._IsOpen(self.entry_ticket):
            return

        if self.option_symbol is not None:
            holding = self.Portfolio[self.option_symbol]
            if holding.Invested:
                return

        chain = None
        try:
            if slice.OptionChains.ContainsKey(self.option.Symbol):
                chain = slice.OptionChains[self.option.Symbol]
        except Exception:
            chain = None

        if chain is None:
            self.Debug("Skipped call selection: no option chain.")
            return

        minimum_expiry = current_date + timedelta(days=7)

        contracts = [
            contract for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        ]

        if not contracts:
            self.Debug("Skipped call selection: no expiration at least 7 days out.")
            return

        expiration = min(contract.Expiry.date() for contract in contracts)

        spy_price = float(self.Securities[self.spy.Symbol].Price)
        if spy_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )

        self.option_symbol = selected.Symbol
        self.entry_fill_price = None
        self.entry_ticket = self.MarketOrder(self.option_symbol, 1)

        self.Debug(
            "Submitted entry: {0}, expiry {1}, strike {2}".format(
                self.option_symbol,
                expiration,
                selected.Strike
            )
        )

    def _EvaluateOpenPositionExit(self, slice):
        if self.option_symbol is None:
            return

        holding = self.Portfolio[self.option_symbol]
        if not holding.Invested:
            return

        expiry_date = self.option_symbol.ID.Date.date()
        current_date = self.Time.date()

        preceding_trading_day = self._PreviousTradingDay(expiry_date)

        if (
            current_date == preceding_trading_day
            and self.Time.hour == 15
            and self.Time.minute >= 45
        ):
            self._SubmitExit("time stop")
            return

        if self.entry_fill_price is None:
            return

        try:
            if not slice.QuoteBars.ContainsKey(self.option_symbol):
                return

            quote = slice.QuoteBars[self.option_symbol]
            if quote.Bid is None or quote.Ask is None:
                return

            bid = float(quote.Bid.Close)
            ask = float(quote.Ask.Close)

            if bid <= 0 or ask <= 0:
                return

            midpoint = (bid + ask) / 2.0

            if midpoint >= 1.50 * self.entry_fill_price:
                self._SubmitExit("50% profit target")
        except Exception:
            return

    def _HandleExpirationProcessing(self):
        if self.option_symbol is None:
            return

        holding = self.Portfolio[self.option_symbol]
        expiry_date = self.option_symbol.ID.Date.date()

        if self.Time.date() >= expiry_date and holding.Invested:
            self.no_entry_date = self.Time.date()
            self._SubmitExit("expiration protection")
            self.Debug("Expiration protection exit submitted.")

    def _SubmitExit(self, reason):
        if self.option_symbol is None:
            return

        holding = self.Portfolio[self.option_symbol]
        quantity = int(holding.Quantity)

        if quantity <= 0:
            return

        if self.exit_ticket is not None and self._IsOpen(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order: " + reason)

        self.exit_ticket = self.MarketOrder(
            self.option_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(
            "Submitted exit: {0}, quantity {1}".format(
                reason,
                quantity
            )
        )

    def _HandleUnexpectedEquityPosition(self):
        equity_holding = self.Portfolio[self.spy.Symbol]

        if equity_holding.Quantity != 0:
            self.Debug(
                "Unexpected SPY equity position detected; liquidating immediately."
            )
            self.Liquidate(self.spy.Symbol, "Unexpected exercise or assignment")

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None
