        self.exit_order_id = None
        self.expiration_block_date = None

        self.equity_liquidation_submitted = False

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()

        # Never intentionally hold through expiration.
        if self.held_option is not None:
            expiry_date = self.held_option.ID.Date.date()
            today = self.Time.date()

            if today >= expiry_date:
                self.expiration_block_date = today
                self.Debug(
                    f"Expiration liquidation: {self.held_option} at {self.Time}"
                )
                self._submit_exit("expiration")
            else:
                previous_trading_day = self._previous_trading_day(expiry_date)

                if (
                    today == previous_trading_day
                    and self.Time.time() >= time(15, 45)
                ):
                    self._submit_exit("time stop")

                else:
                    self._check_profit_target(slice)

        # Build and process the current five-minute bar from minute data.
        if self.spy in slice.Bars:
            self._process_minute_bar(slice.Bars[self.spy], slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        end = minute_bar.EndTime.replace(second=0, microsecond=0)
        local_time = end.time()

        # Regular session minute bars end from 09:31 through 16:00.
        if local_time <= time(9, 30) or local_time > time(16, 0):
            return

        minute = end.hour * 60 + end.minute
        bucket_end_minutes = ((minute - 30 + 4) // 5) * 5 + 30
        bucket_end = end.replace(
            hour=bucket_end_minutes // 60,
            minute=bucket_end_minutes % 60
        )

        if self.bucket_end is not None and bucket_end != self.bucket_end:
            self._finalize_bucket(slice)

        if self.bucket_end != bucket_end:
            self.bucket_end = bucket_end
            self.bucket_bars = {}

        # Preserve only one bar for each minute endpoint.
        self.bucket_bars[end] = minute_bar

        # A completed five-minute bar must contain all five minute bars.
        expected = [
            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if all(t in self.bucket_bars for t in expected):
            self._finalize_bucket(slice)

    def _finalize_bucket(self, slice: Slice):
        if self.bucket_end is None:
            return

        bucket_end = self.bucket_end
        expected = [
            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if not all(t in self.bucket_bars for t in expected):
            self.bucket_end = None
            self.bucket_bars = {}
            return

        bars = [self.bucket_bars[t] for t in expected]
        close = bars[-1].Close

        old_fast = self.fast.Current.Value if self.fast.IsReady else None
        old_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bucket_end, close)
        self.slow.Update(bucket_end, close)

        bullish_cross = (
            old_fast is not None
            and old_slow is not None
            and self.fast.IsReady
            and self.slow.IsReady
            and old_fast <= old_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        self.previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self.previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.bucket_end = None
        self.bucket_bars = {}

        if not bullish_cross:
            return

        bar_time = bucket_end.time()
        if not (time(9, 45) <= bar_time <= time(14, 30)):
            return

        if self.expiration_block_date == self.Time.date():
            return

        self._try_enter(slice, close)

    def _try_enter(self, slice: Slice, spy_price: float):
        if self.held_option is not None or self.entry_order_id is not None:
            return

        if self.option_symbol not in slice.OptionChains:
            self.Debug(f"Skipped entry: no option chain at {self.Time}")
            return

        chain = slice.OptionChains[self.option_symbol]
        current_date = self.Time.date()

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= current_date + timedelta(days=7)
        })

        if not expirations:
            self.Debug(f"Skipped entry: no valid expiration at {self.Time}")
            return

        selected_expiration = expirations[0]
        minimum_strike = 1.01 * float(spy_price)

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiration
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"Skipped entry: no qualifying call for {selected_expiration}"
            )
            return

        selected = min(
            candidates,
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )

        self.entry_order_id = None
        ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.entry_order_id = ticket.OrderId

    def _check_profit_target(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self.exit_order_id is not None:
            return

        if self.held_option not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self.held_option]
        bid = quote.Bid.Close if quote.Bid is not None else None
        ask = quote.Ask.Close if quote.Ask is not None else None

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (float(bid) + float(ask)) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason: str):
        if self.held_option is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self._cancel_open_exit_order()

        ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=f"Option exit: {reason}"
        )
        self.exit_order_id = ticket.OrderId

        self.Debug(
            f"Exit submitted: {self.held_option}, reason={reason}, "
            f"quantity={quantity}"
        )

    def _cancel_open_exit_order(self):
        if self.exit_order_id is None:
            return

        ticket = self.Transactions.GetOrderTicket(self.exit_order_id)
        if ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ):
            ticket.Cancel("Replaced by another exit")

        self.exit_order_id = None

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_order_id is not None
            and order_event.OrderId == self.entry_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = float(order_event.FillPrice)
                self.held_option = order_event.Symbol
                self.entry_order_id = None

                self.Debug(
                    f"Entry filled: {self.held_option}, "
                    f"price={self.entry_price}"
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_order_id = None

        if (
            self.exit_order_id is not None
            and order_event.OrderId == self.exit_order_id
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(f"Exit filled: {order_event.Symbol}")
            self.exit_order_id = None
            self.held_option = None
            self.entry_price = None

        if order_event.Symbol == self.spy:
            if order_event.Status == OrderStatus.Filled:
                self.equity_liquidation_submitted = False

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug(
            f"Unexpected assignment/exercise handling: "
            f"{assignment_event.Symbol}"
        )
        self._liquidate_unexpected_spy_position()

    def OnExerciseOrder(self, exercise_event: OrderEvent):
        self.Debug(
            f"Unexpected exercise handling: {exercise_event.Symbol}"
        )
        self._liquidate_unexpected_spy_position()

    def _handle_unexpected_spy_position(self):
        if self.Portfolio[self.spy].Quantity != 0:
            self._liquidate_unexpected_spy_position()

    def _liquidate_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity == 0 or self.equity_liquidation_submitted:
            return

        self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected exercise/assignment liquidation"
        )
        self.equity_liquidation_submitted = True

        self.Debug(
            f"Liquidated unexpected SPY equity position: quantity={quantity}"
        )

    def _previous_trading_day(self, date_value):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = date_value - timedelta(days=1)

        while not exchange_hours.IsDateOpen(
            datetime.combine(candidate, time.min)
        ):
            candidate -= timedelta(days=1)

        return candidate
