        if end.time() <= time(9, 30) or end.time() > time(16, 0):
            return

        minutes_from_open = (
            end.hour * 60 + end.minute
        ) - (9 * 60 + 30)

        bucket_end = datetime.combine(
            end.date(),
            time(9, 30)
        ) + timedelta(
            minutes=((minutes_from_open // 5) + 1) * 5
        )

        if self.bucket_end != bucket_end:
            if self.bucket_end is not None and self.bucket_count == 5:
                self.CompleteFiveMinuteBar(
                    self.bucket_end,
                    self.bucket_close
                )

            self.bucket_end = bucket_end
            self.bucket_last_end = None
            self.bucket_count = 0
            self.bucket_close = None

        if self.bucket_last_end is not None:
