        if today >= expiry:
            self.expiration_block_date = today
            self.SubmitExit("Expiration protection")
            return

        previous_trading_day = self.PreviousTradingDate(expiry)

        if (
            today == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self.SubmitExit("Pre-expiration time stop")
            return

        if self.entry_price is None:
            return

        if self.OrderIsOpen(self.exit_ticket):
            return

        contract = None

        for chain in slice.OptionChains.Values:
            if self.held_option in chain.Contracts:
                contract = chain.Contracts[self.held_option]
                break

        if contract is None:
            return

        bid = contract.BidPrice
